"""Verify the versioned admit successor and use its existing offline installer."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import platform
import subprocess
import sys
import tempfile
import types
from pathlib import Path

PACKET_SHA = '2e98f86045a516c697eb47dac2735bd64da68bc3a0fca4ab16716013eeb2e108'
PAYLOAD_SHA = '6222c0272c2481916e848a18cd869d50289a7b114bcc36acb88f70d2e5d77047'
VERIFIER_SHA = "032febe109cf145c65f5edaf14403fc58e7b4e93397535d0327e5ce1a65c6ca9"
ARCHIVE = 'aware-canonical-bounded-runtime-source-notice-v1.tar.gz'


def new_target(target: Path) -> None:
    if target.exists() or target.is_symlink():
        raise ValueError("installation_target_must_be_new")
    if not target.parent.is_dir() or target.parent.is_symlink():
        raise ValueError("existing_regular_parent_required")


def load_verifier(root: Path) -> types.ModuleType:
    # Public placement is protocols/install.py; release material is separate.
    path = root.parent / "releases" / "canonical-supplied-runtime-fs-internal-v1" / "archive_verifier.py"
    if path.is_symlink() or not path.is_file():
        raise ValueError("regular_verifier_required")
    body = path.read_bytes()
    if hashlib.sha256(body).hexdigest() != VERIFIER_SHA:
        raise ValueError("verifier_digest_changed")
    module = types.ModuleType("accepted_preview_archive_verifier")
    exec(compile(body, str(path), "exec"), module.__dict__)  # noqa: S102 -- pinned verifier only
    return module


def clean_environment(interpreter: Path) -> dict[str, str]:
    environment = {
        key: value
        for key, value in os.environ.items()
        if key in {"PATH", "HOME", "LANG", "LC_ALL", "TMPDIR"}
    }
    environment.update(
        PYTHON_BIN=str(interpreter),
        PIP_NO_INDEX="1",
        PIP_NO_CACHE_DIR="1",
        PIP_CONFIG_FILE=os.devnull,
        PYTHONDONTWRITEBYTECODE="1",
    )
    return environment


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--python-executable", type=Path, required=True)
    parser.add_argument("--venv", type=Path, required=True)
    args = parser.parse_args()
    interpreter = args.python_executable.expanduser().resolve(strict=True)
    version = subprocess.check_output(
        [
            str(interpreter),
            "-I",
            "-B",
            "-c",
            "import sys; print('.'.join(map(str,sys.version_info[:2])))",
        ],
        text=True,
    ).strip()
    if version != "3.12":
        raise ValueError("python_minor_mismatch:3.12:" + version)
    if sys.platform != "linux" or platform.machine() != "x86_64":
        raise ValueError("linux_x86_64_required")
    target = args.venv.expanduser().absolute()
    new_target(target)
    root = Path(__file__).resolve().parent
    archive = root.parent / "releases" / _STAGING["release_id"] / ARCHIVE
    retained, inner_directory, retained_source = _stage_original(root, archive)
    environment = clean_environment(interpreter)
    try:
        new_target(target)
        subprocess.run(
            ["/bin/sh", str(inner_directory / "install.sh"), str(target)],
            env=environment,
            check=True,
        )
        subprocess.run(
            [str(target / "bin/python"), "-I", "-B", "-m", "pip", "check"],
            env=environment,
            check=True,
        )
    except (OSError, ValueError, subprocess.CalledProcessError):
        print(
            json.dumps(
                {
                    "status": "installation_failed",
                    "retained_evidence": str(retained),
                    "venv": str(target),
                }
            ),
            file=sys.stderr,
        )
        raise
    _release_original_staging()
    print(
        json.dumps(
            {
                "status": "installed",
                "packet_sha256": PACKET_SHA,
                "payload_sha256": PAYLOAD_SHA,
                "venv": str(target),
                "retained_source_and_notices": str(retained_source),
            },
            sort_keys=True,
        )
    )
    return 0


